\[PF_1 + PF_2 = d.\]Find $d.$

[asy]
unitsize(0.3 cm);

int i, n = 10;

for (i = -n; i <= n; ++i) {
  draw((i,-n)--(i,n),gray(0.7));
  draw((-n,i)--(n,i),gray(0.7));
}

draw((0,-n)--(0,n));
draw((-n,0)--(n,0));

draw(shift((-1,0))*xscale(7)*yscale(5)*Circle((0,0),1),red);

dot((-1,0));
[/asy]

